#include <iostream>
using namespace std;

//Driver Code Ends

class Node {
  public:
    int data;
    Node *next;
    Node(int x) {
        data = x;
        next = nullptr;
    }
};

Node *removeDuplicates(Node *head) {

    // Unordered map to track unique node values
    unordered_set<int>st;

    // Initialize pointers for traversing the original list
    // and building the new list without duplicates
    Node *new_head = nullptr;
    Node *tail = nullptr;

    // Traverse the original list
    Node *curr = head;
    while (curr != nullptr) {

        // Check if the current node's data is not in the map
        if (st.find(curr->data) == st.end()) {

            // Create a new node for the unique data
            Node *new_node = new Node(curr->data);

            // If new_head is null, this is the
            // first unique node
            if (new_head == nullptr) {
                new_head = new_node;
                tail = new_head;
            }
            else {
                // Append the new node to the end
                // of the new list
                tail->next = new_node;
                tail = new_node;
            }

            // Mark this data as encountered
            st.insert(curr->data);
        }

        // Move to the next node in the original list
        curr = curr->next;
    }

    // delete old list
    curr = head;
    while (curr != nullptr) {
        Node* temp = curr;
        curr = curr->next;
        delete temp;
    }

    // Return the head of the new list with
    // duplicates removed
    return new_head;
}

//Driver Code Starts

void printList(Node *node) {
    while (node != NULL) {
        cout << node->data << " ";
        node = node->next;
    }
    cout << endl;
}

int main() {

    // Create a sorted linked list
    // 11->11->11->13->13->20
    Node *head = new Node(11);
    head->next = new Node(11);
    head->next->next = new Node(11);
    head->next->next->next = new Node(13);
    head->next->next->next->next = new Node(13);
    head->next->next->next->next->next = new Node(20);

    printList(head);

    head = removeDuplicates(head);

    printList(head);

    return 0;
}
